WITH m AS (SELECT strftime('%Y-%m',order_date) month, SUM(revenue) revenue FROM sales GROUP BY 1), p AS (SELECT *, LAG(month) OVER (ORDER BY month) prev_month, LAG(revenue) OVER (ORDER BY month) prev_revenue FROM m) SELECT month, ROUND(revenue,2) revenue, CASE WHEN date(prev_month||'-01','+1 month')=date(month||'-01') THEN ROUND(100.0*(revenue-prev_revenue)/NULLIF(prev_revenue,0),2) END mom_growth_pct FROM p ORDER BY month;
